select ISNULL(SUM(t.Amount), 0)Amount,t.ContractNo from ( SELECT AR_ReceiptTransactionHeader.Amount,ContractNo FROM AR_ReceiptTransactionHeader LEFT JOIN ( SELECT DISTINCT SAL_OrderHeader.OrderID, SAL_OrderHeader.CompanyID, SAL_OrderHeader.PeriodID, SAL_OrderHeader.SaleContractTypeID, SAL_OrderHeader.CustomerID, SAL_OrderHeader.BrokerID, SAL_OrderHeader.PaymentTermID, SAL_OrderHeader.Season, SAL_OrderHeader.ContractNo, SAL_OrderHeader.ContractDate, SAL_OrderHeader.PaymentDate, SAL_OrderHeader.DispatchDate, SAL_OrderHeader.DTRENo, SAL_OrderHeader.DTREDate, SAL_OrderHeader.IsApproved, SAL_OrderHeader.ApprovedBy, SAL_OrderHeader.ApprovalDate, SAL_OrderHeader.Remarks, SAL_OrderHeader.IsPaid, SAL_OrderHeader.PaidAmount, SAL_OrderHeader.Status, SAL_OrderHeader.CreatedBy, SAL_OrderHeader.CreateDate, SAL_OrderHeader.UpdatedBy, SAL_OrderHeader.UpdateDate, SAL_OrderHeader.CreatedByValue, SAL_OrderHeader.UpdatedByValue, SAL_OrderHeader.StatusCode, SAL_OrderHeader.ClosedCode, SAL_OrderHeader.ClosedOn, SAL_OrderHeader.TotalAmount, SAL_OrderHeader.Held, SAL_OrderHeader.ApprovalRequired, SAL_OrderHeader.Cancelled, SAL_OrderHeader.CancelledOn, SAL_OrderHeader.CancelledBy, SAL_OrderHeader.Frozen, SAL_OrderHeader.referenceno, SAL_OrderHeader.DepartmentID, SAL_OrderHeader.FreightTermsCode, SAL_OrderHeader.FreightDetail, SAL_OrderHeader.InspectionBy, SAL_OrderHeader.PaymentTypeID, SAL_OrderHeader.CommissionAmount, SAL_OrderHeader.CommissionCOA, SAL_OrderHeader.InsuranceAmount, SAL_OrderHeader.InsuranceCOA, SAL_OrderHeader.ChartOfAccountID, SAL_OrderHeader.CheckListChecked, SAL_OrderHeader.AdvanceAmountPercentage, SAL_OrderHeader.BilledTo, SAL_OrderHeader.Commission, SAL_OrderHeader.TransactionType, SAL_OrderHeader.Quality, SAL_OrderHeader.AmountType, SAL_OrderHeader.ShipTo, SAL_OrderHeader.appid FROM SAL_DispatchHeader INNER JOIN INV_StockTransactionHeader ON INV_StockTransactionHeader.DocumentTypeID = SAL_DispatchHeader.DocumentTypeID AND INV_StockTransactionHeader.DocumentNo = SAL_DispatchHeader.DispatchNo AND INV_StockTransactionHeader.CompanyID = SAL_DispatchHeader.CompanyID AND INV_StockTransactionHeader.PeriodID = SAL_DispatchHeader.PeriodID AND INV_StockTransactionHeader.Status = 1 INNER JOIN INV_StockTransactionDetail ON INV_StockTransactionDetail.CompanyID = INV_StockTransactionHeader.CompanyID AND INV_StockTransactionDetail.PeriodID = INV_StockTransactionHeader.PeriodID AND INV_StockTransactionDetail.StockTransactionID = INV_StockTransactionHeader.StockTransactionID AND INV_StockTransactionDetail.Status = 1 INNER JOIN SAL_DeliveryOrderDetail ON SAL_DeliveryOrderDetail.CompanyID = INV_StockTransactionDetail.CompanyID AND SAL_DeliveryOrderDetail.PeriodID = INV_StockTransactionDetail.PeriodID AND SAL_DeliveryOrderDetail.DODetailID = INV_StockTransactionDetail.SourceLineID
--AND SAL_DeliveryOrderDetail.DOHeaderID = INV_StockTransactionDetail.SourceCode
AND SAL_DeliveryOrderDetail.DOHeaderID = INV_StockTransactionDetail.SourceHeaderID
AND SAL_DeliveryOrderDetail.Status = 1 INNER JOIN SAL_OrderHeader ON SAL_OrderHeader.CompanyID = SAL_DeliveryOrderDetail.CompanyID AND SAL_OrderHeader.PeriodID = SAL_DeliveryOrderDetail.PeriodID AND SAL_OrderHeader.OrderID = SAL_DeliveryOrderDetail.SalesOrderHeaderID AND SAL_OrderHeader.Status = 1 WHERE SAL_DispatchHeader.CompanyID = @CompanyID AND SAL_DispatchHeader.PeriodID = @PeriodID AND SAL_DispatchHeader.Status = 1 AND INV_StockTransactionHeader.StockTransactionID = @SourceHeaderID ) AS tbl ON tbl.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND tbl.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND tbl.OrderID = AR_ReceiptTransactionHeader.SourceHeaderID AND tbl.Status = 1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND SET_DocumentType.Status = 1 AND SET_DocumentType.DocumentType = 'Advance Against SO' WHERE AR_ReceiptTransactionHeader.CompanyID = @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.Status = 1 {0}
) t where t.contractno is not null group by t.contractno

SELECT DISTINCT AR_ReceiptTransactionHeader.CompanyID , AR_ReceiptTransactionHeader.PeriodID , AR_SET_Customer.CustomerID , DocumentNo , ( CASE WHEN AR_ReceiptCustomerDetail.TransactionType = 'Debit' THEN ISNULL(ISNULL(AR_ReceiptCustomerDetail.amount,AR_ReceiptCustomerDetail.Amount) * -1, 0) WHEN AR_ReceiptCustomerDetail.TransactionType = 'Credit' THEN ISNULL(ISNULL(AR_ReceiptCustomerDetail.amount,AR_ReceiptCustomerDetail.Amount), 0) ELSE ISNULL(ISNULL(AR_ReceiptCustomerDetail.amount,AR_ReceiptCustomerDetail.Amount), 0) END ) AS Amount --WHEN AP_Payment_AccountsDetail.TransactionType ='Debit' THEN ISNULL(AP_Payment_AccountsDetail.Amount , 0) else ISNULL(AP_Payment_AccountsDetail.Amount, 0) end) as Amount , SET_DocumentType.DocumentType FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 AND SET_DocumentType.DocumentType NOT LIKE '%advance%against%SO%' Left JOIN AR_ReceiptCustomerDetail ON AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptCustomerDetail.Status = 1 LEFT JOIN AR_ReceiptInvoicesDetail ON AR_ReceiptInvoicesDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptInvoicesDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptInvoicesDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptInvoicesDetail.Status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 LEFT JOIN AR_ReceiptAccountsDetail ON AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID -- AND AR_ReceiptAccountsDetail.IsBP <> 0 AND AR_ReceiptAccountsDetail.TransactionType = 'Credit' AND AR_ReceiptAccountsDetail.Status = 1 LEFT JOIN AR_ReceiptBanksDetail ON AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID -- AND AR_ReceiptAccountsDetail.IsBP <> 0 AND AR_ReceiptBanksDetail.TransactionType = 'Credit' AND AR_ReceiptBanksDetail.Status = 1 LEFT JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TYPECODE = AR_ReceiptCustomerDetail.BusinessPartnerTypeID
{0}
UNION ALL
SELECT DISTINCT AR_ReceiptTransactionHeader.CompanyID , AR_ReceiptTransactionHeader.PeriodID , AR_SET_Customer.CustomerID AS SupplierID , DocumentNo , AR_ReceiptTransactionHeader.Amount , --WHEN AP_Payment_AccountsDetail.TransactionType ='Debit' THEN ISNULL(AP_Payment_AccountsDetail.Amount , 0) else ISNULL(AP_Payment_AccountsDetail.Amount, 0) end) as Amount
SET_DocumentType.DocumentType FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 AND SET_DocumentType.DocumentType LIKE '%advance%against%SO%' left JOIN AR_ReceiptCustomerDetail ON AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptCustomerDetail.Status = 1 LEFT JOIN AR_ReceiptInvoicesDetail ON AR_ReceiptInvoicesDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptInvoicesDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptInvoicesDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptInvoicesDetail.Status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 LEFT JOIN AR_ReceiptAccountsDetail ON AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID -- AND AR_ReceiptAccountsDetail.IsBP <> 0 AND AR_ReceiptAccountsDetail.TransactionType = 'Debit' AND AR_ReceiptAccountsDetail.Status = 1 LEFT JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TYPECODE = AR_ReceiptCustomerDetail.BusinessPartnerTypeID
{0}
--UNION ALL
--SELECT DISTINCT --AR_ReceiptTransactionHeader.CompanyID , --AR_ReceiptTransactionHeader.PeriodID , --AR_SET_Customer.CustomerID , --DocumentNo , --( CASE WHEN AR_ReceiptBanksDetail.TransactionType = 'Credit' --THEN ISNULL(ISNULL(AR_ReceiptBanksDetail.amount,AR_ReceiptBanksDetail.Amount) --* -1, 0) --WHEN AR_ReceiptBanksDetail.TransactionType = 'Debit' --THEN ISNULL(ISNULL(AR_ReceiptBanksDetail.amount,AR_ReceiptBanksDetail.Amount), --0) --ELSE ISNULL(ISNULL(AR_ReceiptBanksDetail.amount,AR_ReceiptBanksDetail.Amount), --0) --END ) AS Amount ----WHEN AP_Payment_AccountsDetail.TransactionType ='Debit' THEN ISNULL(AP_Payment_AccountsDetail.Amount , 0) else ISNULL(AP_Payment_AccountsDetail.Amount, 0) end) as Amount --, --SET_DocumentType.DocumentType --FROM SET_DocumentType --INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID --AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID --AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID --AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 --AND SET_DocumentType.DocumentType NOT LIKE '%advance%against%SO%' --Left JOIN AR_ReceiptCustomerDetail ON AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID -- AND AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID -- AND AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID -- AND AR_ReceiptCustomerDetail.Status = 1 --LEFT JOIN AR_ReceiptInvoicesDetail ON AR_ReceiptInvoicesDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID -- AND AR_ReceiptInvoicesDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID -- AND AR_ReceiptInvoicesDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID -- AND AR_ReceiptInvoicesDetail.Status=1 --INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID --AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID --AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 --LEFT JOIN AR_ReceiptAccountsDetail ON AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID ---- AND AR_ReceiptAccountsDetail.IsBP <> 0 -- AND AR_ReceiptAccountsDetail.TransactionType = 'Debit' -- AND AR_ReceiptAccountsDetail.Status = 1 --LEFT JOIN AR_ReceiptBanksDetail ON AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID ---- AND AR_ReceiptAccountsDetail.IsBP <> 0 --AND AR_ReceiptBanksDetail.TransactionType = 'Debit' --AND AR_ReceiptBanksDetail.Status = 1 --LEFT JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID -- AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID -- AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID -- AND AR_SET_BusinessPartnerTypes.TYPECODE = AR_ReceiptCustomerDetail.BusinessPartnerTypeID
-- {0}
