SELECT DISTINCT AP_PaymentHeader.CompanyID , AP_PaymentHeader.PeriodID , AR_SET_Customer.CustomerID AS SupplierID , DocumentNo , ( CASE WHEN AP_PaymentSupplierDetail.TransactionType = 'Debit' THEN ISNULL(ISNULL(AP_PaymentInvoicesDetail.amount,AP_PaymentSupplierDetail.Amount) * -1, 0) WHEN AP_PaymentSupplierDetail.TransactionType = 'Credit' THEN ISNULL(ISNULL(AP_PaymentInvoicesDetail.amount,AP_PaymentSupplierDetail.Amount), 0) ELSE ISNULL(ISNULL(AP_PaymentInvoicesDetail.amount,AP_PaymentSupplierDetail.Amount), 0) END ) AS Amount --WHEN AP_Payment_AccountsDetail.TransactionType ='Debit' THEN ISNULL(AP_Payment_AccountsDetail.Amount , 0) else ISNULL(AP_Payment_AccountsDetail.Amount, 0) end) as Amount , SET_DocumentType.DocumentType FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 -- AND SET_DocumentType.DocumentType NOT LIKE '%direct%payment%jv%' INNER JOIN AP_PaymentSupplierDetail ON AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID AND AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID AND AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID AND AP_PaymentSupplierDetail.Status = 1 LEFT JOIN dbo.AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = AP_PaymentHeader.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = AP_PaymentHeader.PeriodID AND AP_PaymentInvoicesDetail.Status=1 INNER JOIN AR_SET_Customer ON AP_PaymentSupplierDetail.SupplierID = AR_SET_Customer.CustomerID AND AP_PaymentSupplierDetail.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentSupplierDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 LEFT JOIN AP_Payment_AccountsDetail ON AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID AND AP_Payment_AccountsDetail.IsBP <> 0 AND AP_Payment_AccountsDetail.TransactionType = 'Credit' AND AP_Payment_AccountsDetail.Status = 1 LEFT JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TYPECODE = AP_PaymentSupplierDetail.BusinessPartnerTypeID
{1}

Select LeaseType ,BankName,Year, sum(OpeningAmount) + sum(ReceiptAmount) - sum(Payment) as PayableForYearEnding,Principal,RentalAmount,0 as FinanceCost from ( select AR_SET_BankAccount.BankAccountNumber, AR_SET_BankAccount.BankAccountName, AR_SET_BankBranch.BankBranchName, isnull( ( select sum(AR_ReceiptTransactionHeader.Amount) from AR_ReceiptTransactionHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 and AR_ReceiptTransactionHeader.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptTransactionHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptTransactionHeader.DocumentDate < @fromDate AND AR_ReceiptTransactionHeader.BankAccountID Is Not Null and AR_ReceiptTransactionHeader.Status = 1 and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + isnull( ( select sum(Case When AR_ReceiptBanksDetail.TransactionType = 'Debit' then AR_ReceiptBanksDetail.Amount Else AR_ReceiptBanksDetail.Amount * -1 End) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate < @fromDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptTransactionHeader.Status = 1 and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) - (isnull( ( select sum(AP_PaymentHeader.Amount) from AP_PaymentHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AP_PaymentHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentHeader.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentHeader.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentHeader.DocumentDate < @fromDate AND AP_PaymentHeader.BankAccountID Is Not Null and AP_PaymentHeader.Status = 1 and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0) + isnull( ( select sum(Case When AP_PaymentBanksDetail.TransactionType = 'Credit' then AP_PaymentBanksDetail.Amount Else AP_PaymentBanksDetail.Amount * -1 End) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate < @fromDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0)) OpeningAmount, isnull( ( select sum(AR_ReceiptTransactionHeader.Amount) Total from AR_ReceiptTransactionHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID =AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptTransactionHeader.CompanyID= AR_SET_BankAccount.CompanyID and AR_ReceiptTransactionHeader.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptTransactionHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptTransactionHeader.DocumentDate between @fromDate and @toDate and AR_ReceiptTransactionHeader.Status = 1 And AR_ReceiptTransactionHeader.BankAccountID is not null and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL( ( select sum(AR_ReceiptBanksDetail.Amount) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate Between @fromDate And @ToDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptBanksDetail.TransactionType = 'Debit' and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL( ( select sum(AP_PaymentBanksDetail.Amount) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate Between @fromDate And @ToDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 And AP_PaymentBanksDetail.TransactionType = 'Debit' and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0) ReceiptAmount, ( ISNULL( ( select sum(AP_PaymentHeader.Amount) From AP_PaymentHeader --INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID --And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID --INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID
WHERE AP_PaymentHeader.CompanyID = @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID And AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.BankAccountID is not null AND AP_PaymentHeader.DocumentDate Between @FromDate AND @ToDate and AP_PaymentHeader.BankAccountID = AR_SET_BankAccount.BankAccountID
), 0) + ISNULL( ( select sum(AR_ReceiptBanksDetail.Amount) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate Between @fromDate And @ToDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptBanksDetail.TransactionType = 'Credit' and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL ( ( select sum(AP_PaymentBanksDetail.Amount) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate Between @fromDate And @ToDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 And AP_PaymentBanksDetail.TransactionType = 'Credit' and AP_PaymentHeader.CompanyID = @CompanyID
), 0) ) Payment ,AR_SET_Bank.BankName ,case LeaseType when 1 then 'Ijarah' when 2 then 'Musharka' when 3 then 'LeaseFinancing' else '' end as LeaseType ,year(FA_LeaseHeader.PurchaseDate) as Year ,isnull(FA_LeaseHeader.Rate,0) as Principal ,isnull(FA_LeaseHeader.RentalAmount,0) as RentalAmount from AR_SET_BankAccount Inner Join AR_SET_BankBranch On AR_SET_BankBranch.BankBranchID = AR_SET_BankAccount.BankBranchID inner join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID inner join FA_LeaseHeader on FA_LeaseHeader.BankBranchID = AR_SET_BankBranch.BankBranchID
where AR_SET_BankAccount.CompanyID = @CompanyID and AR_SET_BankAccount.PeriodID = @PeriodID And AR_SET_BankAccount.Status = 1 and FA_LeaseHeader.CompanyID = @CompanyID
and FA_LeaseHeader.LeaseDate between @FromDate and @Todate
) Bank group by LeaseType ,BankName,Year,Principal,RentalAmount

Select LeaseType ,BankName,sum(OpeningAmount) as OpeningBalance, sum(ReceiptAmount) as AddtionAmount ,sum(OpeningAmount) + sum(ReceiptAmount) as Total , sum(Payment) as PaymentAmount ,sum(OpeningAmount) + sum(ReceiptAmount) - sum(Payment) as ClosingBalance ,sum(OpeningAmount) + sum(ReceiptAmount) - sum(Payment) as PayableForYearEnding from ( select AR_SET_BankAccount.BankAccountNumber, AR_SET_BankAccount.BankAccountName, AR_SET_BankBranch.BankBranchName, isnull( ( select sum(AR_ReceiptTransactionHeader.Amount) from AR_ReceiptTransactionHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 and AR_ReceiptTransactionHeader.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptTransactionHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptTransactionHeader.DocumentDate < @fromDate AND AR_ReceiptTransactionHeader.BankAccountID Is Not Null and AR_ReceiptTransactionHeader.Status = 1 and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + isnull( ( select sum(Case When AR_ReceiptBanksDetail.TransactionType = 'Debit' then AR_ReceiptBanksDetail.Amount Else AR_ReceiptBanksDetail.Amount * -1 End) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate < @fromDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptTransactionHeader.Status = 1 and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) - (isnull( ( select sum(AP_PaymentHeader.Amount) from AP_PaymentHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AP_PaymentHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentHeader.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentHeader.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentHeader.DocumentDate < @fromDate AND AP_PaymentHeader.BankAccountID Is Not Null and AP_PaymentHeader.Status = 1 and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0) + isnull( ( select sum(Case When AP_PaymentBanksDetail.TransactionType = 'Credit' then AP_PaymentBanksDetail.Amount Else AP_PaymentBanksDetail.Amount * -1 End) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate < @fromDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0)) OpeningAmount, isnull( ( select sum(AR_ReceiptTransactionHeader.Amount) Total from AR_ReceiptTransactionHeader Inner Join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID Inner Join AR_SET_Bank on AR_SET_Bank.BankID =AR_SET_BankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptTransactionHeader.CompanyID= AR_SET_BankAccount.CompanyID and AR_ReceiptTransactionHeader.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptTransactionHeader.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptTransactionHeader.DocumentDate between @fromDate and @toDate and AR_ReceiptTransactionHeader.Status = 1 And AR_ReceiptTransactionHeader.BankAccountID is not null and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL( ( select sum(AR_ReceiptBanksDetail.Amount) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate Between @fromDate And @ToDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptBanksDetail.TransactionType = 'Debit' and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL( ( select sum(AP_PaymentBanksDetail.Amount) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate Between @fromDate And @ToDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 And AP_PaymentBanksDetail.TransactionType = 'Debit' and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0) ReceiptAmount, ( ISNULL( ( select sum(AP_PaymentHeader.Amount) From AP_PaymentHeader --INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID --And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID --INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID
WHERE AP_PaymentHeader.CompanyID = @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID And AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.BankAccountID is not null AND AP_PaymentHeader.DocumentDate Between @FromDate AND @ToDate and AP_PaymentHeader.BankAccountID = AR_SET_BankAccount.BankAccountID
), 0) + ISNULL( ( select sum(AR_ReceiptBanksDetail.Amount) from AR_ReceiptTransactionHeader Inner Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AR_ReceiptTransactionHeader.StatusCode = 1 --and AR_ReceiptBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AR_ReceiptBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AR_ReceiptBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AR_ReceiptTransactionHeader.DocumentDate Between @fromDate And @ToDate AND AR_ReceiptBanksDetail.BankAccountID Is Not Null and AR_ReceiptBanksDetail.Status = 1 And AR_ReceiptBanksDetail.TransactionType = 'Credit' and AR_ReceiptTransactionHeader.CompanyID = @CompanyID and AR_ReceiptTransactionHeader.PeriodID = @PeriodID and AR_ReceiptTransactionHeader.FiscalID = @FiscalID
), 0) + ISNULL( ( select sum(AP_PaymentBanksDetail.Amount) from AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND Set_DocumentType.Status = 1
where AP_PaymentHeader.StatusCode = 1 --and AP_PaymentBanksDetail.CompanyID = AR_SET_BankAccount.CompanyID and AP_PaymentBanksDetail.PeriodID = AR_SET_BankAccount.PeriodID and AP_PaymentBanksDetail.BankAccountID = AR_SET_BankAccount.BankAccountID and AP_PaymentBanksDetail.BankBranchID = AR_SET_BankAccount.BankBranchID and AP_PaymentHeader.DocumentDate Between @fromDate And @ToDate AND AP_PaymentBanksDetail.BankAccountID Is Not Null and AP_PaymentBanksDetail.Status = 1 And AP_PaymentHeader.Status = 1 And AP_PaymentBanksDetail.TransactionType = 'Credit' and AP_PaymentHeader.CompanyID = @CompanyID and AP_PaymentHeader.PeriodID = @PeriodID and AP_PaymentHeader.FiscalID = @FiscalID
), 0) ) Payment ,AR_SET_Bank.BankName ,case LeaseType when 1 then 'Ijarah' when 2 then 'Musharka' when 3 then 'LeaseFinancing' else '' end as LeaseType from AR_SET_BankAccount Inner Join AR_SET_BankBranch On AR_SET_BankBranch.BankBranchID = AR_SET_BankAccount.BankBranchID inner join AR_SET_Bank on AR_SET_Bank.BankID = AR_SET_BankBranch.BankID inner join FA_LeaseHeader on FA_LeaseHeader.BankBranchID = AR_SET_BankBranch.BankBranchID ​ where AR_SET_BankAccount.CompanyID = @CompanyID and AR_SET_BankAccount.PeriodID = @PeriodID And AR_SET_BankAccount.Status = 1 and FA_LeaseHeader.LeaseDate between @FromDate and @Todate
) Bank group by LeaseType ,BankName
